public protocol PhoneProtocol: AnyObject, Sendable {
    
    /**
     * Close `agent`: its session ends, and its tile leaves the board. Whether it was there to
     * close; not when it was closed already.
     */
    func closeAgent(agent: AgentRef) async throws  -> Bool
    
    /**
     * What `agent` changed in the folder it runs in.
     */
    func diff(agent: AgentRef) async throws  -> Diff
    
    /**
     * Interrupt `agent`'s turn, with the keys its manifest says: whether it was; not when it was
     * neither working nor waiting on the person.
     */
    func interrupt(agent: AgentRef) async throws  -> Bool
    
    /**
     * Start an agent in `workspace`, which `device` holds, as `start` says: the agent, on its
     * board from then on.
     */
    func start(device: String, workspace: String, start: Start) async throws  -> AgentRef
    
    /**
     * What may be started in `workspace`, which `device` holds.
     */
    func startable(device: String, workspace: String) async throws  -> Startable
    
    /**
     * Follow what `agent` and the person say to each other: `listener` is told the last of it the
     * device sends, then each piece as it is said, and why it ended if it does.
     */
    func conversation(agent: AgentRef, listener: ConversationListener)  -> Conversation
    
    /**
     * Answer what `agent` waits on the person for, the wait that began at `since`: whether it
     * landed; not when it waits on that no more, or was answered.
     */
    func answer(agent: AgentRef, since: UInt64, answer: Answer) async throws  -> Bool
    
    /**
     * `listener` is told each new overview's revision, until it stops.
     */
    func follow(listener: OverviewListener)  -> Following
    
    /**
     * The phone's id: its device key's public half, in hex.
     */
    func id()  -> String
    
    /**
     * The app went to the background: the connections close.
     */
    func onBackground() 
    
    /**
     * The app came to the foreground: every device is dialled now (§3.2).
     */
    func onForeground() 
    
    /**
     * The newest overview: what each device last said, until it says more (§3.1).
     */
    func overview()  -> Overview
    
    /**
     * Pair with the app whose link, the QR code's text, was scanned: the phone is that app's
     * person's from then on, and reaches their devices anew.
     */
    func pair(link: String) async throws  -> Paired
    
    /**
     * Whose devices these are, as their app said: none before one did.
     */
    func person()  -> Person?
    
    /**
     * Send `agent` a message, one line, typed in as its next prompt: whether it went; not when no
     * agent runs there.
     */
    func send(agent: AgentRef, text: String) async throws  -> Bool
    
    /**
     * Unpair from `device`, by its id: whether it was told; one that was not still lists the
     * phone, and is to be unpaired there too.
     */
    func unpair(device: String) async throws  -> Bool
    
    /**
     * Watch `agent`'s terminal: `listener` is told of each frame, its keyboard and its end. It is
     * watched across the background, the foreground and the device's reconnects, until the
     * session ends or the watch is stopped.
     */
    func watch(agent: AgentRef, listener: ScreenListener)  -> Watch
    
    /**
     * Be told at `at` what happens on the person's devices (spec/push.md): through the network's
     * push server when it has one that tells phones there, else directly; each device is given
     * where.
     */
    func pushTo(at: PushAt) async throws  -> PushTold
    
    /**
     * The VAPID key (RFC 8292, base64url) of the push server on the person's network that tells
     * phones through UnifiedPush: for the app to give its distributor as it registers (Android's
     * `UnifiedPush.register(…, vapid)`), so one that asks for a key takes what that server posts.
     * None on a network without such a server.
     */
    func pushVapid()  -> String?
    
    /**
     * What `body`, a notice the app's push service handed it, says: none for one not to show (a
     * device back the phone did not find away, or a kind it does not know). Its agent's device is
     * the one that holds its workspace, as last heard, else as the devices say when asked now, all
     * at once and for three seconds at most, so it is read within a push handler's few seconds:
     * none ("") when none said by then.
     */
    func readNotice(body: Data) async throws  -> Notice?
    
    /**
     * Show the view `view` on `workspace`, on `device`, on `screen`: what its page posts goes in
     * by `post`, and `listener` is told what its host says, and when it starts again or ends. It
     * goes on across the background, the foreground and the device's reconnects until stopped.
     */
    func openView(device: String, workspace: String, view: String, screen: Screen, listener: ViewListener)  -> ViewSession
    
    /**
     * The file at `path` in the view `view`, from `device`, which holds `workspace`: served to
     * the view's web view as it comes, under its policy.
     */
    func viewFile(device: String, workspace: String, view: String, path: String) async throws  -> ViewFile
    
    /**
     * The community views `device` offers a phone, for `workspace`, which it holds.
     */
    func views(device: String, workspace: String) async throws  -> [ViewInfo]
    
}
